404	export async function createEvent(
405	  data: EventCreateRequestDTO,
406	  e2eExtras?: E2EEventExtras,
407	): Promise<EventDetailResponseDTO> {
408	  if (isE2ETestMode && e2eEventsStore) {
409	    return createE2EEvent(data, e2eExtras);
410	  }
411	
412	  const { apiUrl, authToken } = await requireMutationAuth();
413	
414	  const response = await fetchWithHmac(`${apiUrl}/events`, {
415	    method: "POST",
416	    headers: {
417	      Accept: "application/json",
418	      "Content-Type": "application/json",
419	      Authorization: `Bearer ${authToken}`,
420	    },
421	    body: JSON.stringify(data),
422	    skipBodySigning: true, // backend ignores body for signature; align client signing
423	  });
424	
425	  if (!response.ok) {
426	    const errorText = await response.text().catch(() => "<unreadable>");
427	    // 2026-07-26 round-5 diagnostic: mirror getAuthenticatedUserExternal so
428	    // server-side logs (and Sentry) expose the redacted JWT iss/aud/exp/sub
429	    // the backend actually rejected. Lets us tell "stale audience" (401) from
430	    // "profile incomplete" (403) without a second round-trip.
431	    const safeClaims = decodeSafeJwtClaims(authToken);
432	    // The backend error body can echo back submitted event fields (title,
433	    // description, url, ...) in validation messages, or leak internal
434	    // details in an unexpected failure — keep the raw body in the
435	    // server-side console.error below, but don't forward it to Sentry
436	    // (a third-party service). Status + length are enough to diagnose from
437	    // there; the full body is still one grep away in the app's own logs.
438	    captureException(
439	      new Error(`createEvent: HTTP ${response.status}`),
440	      {
441	        tags: { section: "events-mutation", endpoint: "createEvent" },
442	        extra: {
443	          status: response.status,
444	          bodyLength: errorText.length,
445	          accessTokenClaims: safeClaims,
446	        },
447	      },
448	    );
449	    // 2026-07-26 round-10 (mirror of uploadEventImage): surface the
450	    // WWW-Authenticate header so Spring's resource-server rejection reason
451	    // (RFC 6750) is one-grep root-caused. The body's empty on resource-server
452	    // failures; the header names invalid_token / insufficient_scope / etc.
453	    console.error(
454	      `createEvent: HTTP ${response.status} \u2014 body=${errorText.slice(0, 200)} \u2014 www-authenticate=${response.headers.get("www-authenticate") ?? "<none>"} \u2014 access_token=${safeClaims}`,
455	    );
456	    // Attach `.status` so callers (actions.ts) can distinguish 401 (stale
457	    // Bearer) from 403 (profileCompleted gate) and route accordingly.
458	    const err = Object.assign(
459	      new Error(`HTTP error! status: ${response.status}, body: ${errorText}`),
460	      { status: response.status },
461	    );
462	    throw err;
463	  }
464	  return response.json();
465	}
