485	      "NEXT_PUBLIC_API_URL is not set — refusing to run mutation against default production URL",
486	    );
487	  }
488	
489	  const apiUrl = getApiUrl();
490	  // Auth is optional — sponsor image uploads use Stripe session, not user login
491	  const authToken = await getAccessTokenFromCookies();
492	  const headers: HeadersInit = { Accept: "application/json" };
493	  if (authToken) {
