505	
506	  if (!response.ok) {
507	    const errorText = await response
508	      .text()
509	      .catch(() => "Unable to read error response");
510	    // 2026-07-26 round-10 diagnostic: surface the WWW-Authenticate header so
511	    // Spring's resource-server rejection reason (RFC 6750) is visible in
512	    // one grep. The 401 body is usually empty for Spring resource-server
513	    // failures; the header is where the actual cause lives (e.g.
514	    // invalid_token vs insufficient_scope vs missing cnf-binding).
515	    console.error(
516	      `uploadEventImage: HTTP ${response.status} -- body=${errorText} -- www-authenticate=${response.headers.get("www-authenticate") ?? "<none>"}`,
517	    );
518	    if (response.status === 413) {
519	      throw new Error(EVENT_IMAGE_UPLOAD_TOO_LARGE_ERROR);
520	    }
521	    throw new Error(
522	      `HTTP error! status: ${response.status}, body: ${errorText}`,
523	    );
524	  }
525	
526	  let payload: unknown;
527	  try {
528	    payload = await response.json();
529	  } catch {
530	    throw new Error("uploadEventImage: invalid JSON response from backend");
531	  }
532	
533	  if (
534	    !payload ||
