536	    typeof (payload as { url?: unknown }).url !== "string" ||
537	    typeof (payload as { publicId?: unknown }).publicId !== "string"
538	  ) {
539	    throw new Error(
540	      "uploadEventImage: backend response missing url/publicId fields",
541	    );
