617	/**
618	 * Fetch events categorized by category.
619	 * During build phase (SSG), calls external API directly to avoid internal proxy issues.
620	 * At runtime (ISR/SSR), uses internal API proxy for better caching and security.
621	 */
622	export async function fetchCategorizedEvents(
623	  maxEventsPerCategory?: number,
624	): Promise<CategorizedEvents> {
625	  const apiUrl = getApiUrl();
626	
627	  // During build phase, bypass internal proxy and call external API directly
628	  // This ensures SSG pages (homepage) can fetch data during next build
629	  if (isBuildPhase) {
630	    try {
631	      const data = await fetchCategorizedEventsExternal(maxEventsPerCategory);
632	      const validated = parseCategorizedEvents(data);
633	      if (!validated) {
634	        console.error("fetchCategorizedEvents: Build phase validation failed");
635	        return {};
636	      }
637	      return validated;
638	    } catch (e) {
639	      console.error(
640	        "fetchCategorizedEvents: Build phase external fetch failed:",
641	        e,
642	      );
643	      return {};
644	    }
645	  }
646	
647	  // Runtime: use direct external API call with caching
648	  // This avoids internal API proxy issues
649	  try {
650	    const params = new URLSearchParams();
651	    if (maxEventsPerCategory !== undefined) {
652	      params.append("maxEventsPerCategory", String(maxEventsPerCategory));
653	    }
654	
655	    const queryString = params.toString() ? `?${params.toString()}` : "";
656	    const finalUrl = `${apiUrl}/events/categorized${queryString}`;
657	
658	    const response = await fetchWithHmac(finalUrl, {
659	      next: { revalidate: 600, tags: ["events", "events:categorized"] },
660	      headers: {
661	        Accept: "application/json",
662	      },
663	    });
664	
665	    if (!response.ok) {
666	      const errorText = await response
667	        .text()
668	        .catch(() => "Unable to read error response");
669	      console.error(
670	        `fetchCategorizedEvents: HTTP error! status: ${response.status}, url: ${finalUrl}, error: ${errorText}`,
671	      );
672	      throw new Error(`HTTP error! status: ${response.status}`);
673	    }
674	    const data = await response.json();
675	    const validated = parseCategorizedEvents(data);
676	    if (!validated || Object.keys(validated).length === 0) {
677	      console.error("fetchCategorizedEvents: Runtime validation failed");
678	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
679	    }
680	    return validated;
681	  } catch {
682	    // If direct fetch fails, try external API helper as fallback (handles edge cases)
683	    try {
684	      const data = await fetchCategorizedEventsExternal(maxEventsPerCategory);
685	      const validated = parseCategorizedEvents(data);
686	      if (validated && Object.keys(validated).length > 0) {
687	        return validated;
688	      }
689	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
690	    } catch (fallbackError) {
691	      // Sanitize error logging to prevent information disclosure
692	      const errorMessage = getSanitizedErrorMessage(fallbackError);
693	      console.error(
694	        "fetchCategorizedEvents: Both direct and external API failed:",
695	        errorMessage,
696	      );
697	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
698	    }
699	  }
700	}
