761	/**
762	 * Insert ads at deterministic positions in the event list.
763	 * Uses fixed spacing instead of Math.random() to ensure the component tree
764	 * is identical across renders — required for cacheComponents (RSC resumption).
765	 */
766	function insertAdsDeterministic(
767	  events: EventSummaryResponseDTO[],
768	  ads: AdEvent[],
769	  spacing = 5,
770	  startFrom = 3,
771	): ListEvent[] {
772	  const result: ListEvent[] = [...events];
773	
774	  ads.forEach((ad, i) => {
775	    // Fixed position: startFrom + i * spacing, adjusted for prior insertions
776	    const index = startFrom + i * (spacing + 1);
777	    if (index <= result.length) {
778	      result.splice(index, 0, ad);
779	    }
780	  });
781	
782	  return result;
783	}
