788	): ListEvent[] {
789	  if (!events.length) {
790	    return [];
791	  }
792	
793	  // Create ad events similar to old implementation
794	  const numberOfAds = Math.ceil(events.length / adFrequencyRatio);
795	  const ads: AdEvent[] = Array.from(
796	    { length: numberOfAds },
797	    (_, i) =>
798	      ({
799	        isAd: true,
800	        id: `ad-${i}`,
801	        images: [],
802	        location: "",
803	        slug: "",
804	      }) as AdEvent,
805	  );
