24-/**
25- * Installs the gtag dataLayer-queueing shim if it isn't there yet, so
26- * `sendGoogleEvent` calls that fire before GoogleScripts' own `lazyOnload`
27- * scripts run (e.g. on a hard navigation, like the OIDC callback landing)
28- * don't silently no-op. Safe to call anywhere: it only ever queues into
29- * `dataLayer` — whether that queue ever reaches Google still depends on
30- * GoogleScripts' existing prod-host/consent gating for the real gtag.js load.
31- *
32- * Pushes the Consent Mode v2 denied default in the same guarded branch as
33- * the shim install, mirroring GoogleScripts' inline GTAG_SHIM script (see
34- * its comment there) - so whichever of the two runs first is the only one
35- * that pushes the default, guaranteeing it's queued before any event either
36- * side sends, without ever double-pushing it.
37- */
38:export const ensureGtag = (): WindowWithGtag | null => {
39-  if (typeof window === "undefined") return null;
40-  const win = window as WindowWithGtag;
41-  win.dataLayer = win.dataLayer || [];
42-
43-  if (typeof win.gtag !== "function") {
44-    win.gtag = function gtag() {
45-      win.dataLayer.push(arguments);
46-    };
47-    win.gtag("consent", "default", CONSENT_MODE_DEFAULTS);
48-  }
49-
50-  return win;
51-};

