56	
57	export async function generateMetadata(props: {
58	  params: Promise<{ eventId: string }>;
59	}): Promise<Metadata> {
60	  const slug = (await props.params).eventId;
61	  const locale = (await rootLocale()) as AppLocale;
62	  // Use the request-independent reader: reading headers() here would make
63	  // metadata dynamic under cacheComponents and mismatch the prerendered shell.
64	  // It throws on transient errors — let that bubble so Next does NOT cache a
65	  // broken render (SWR keeps the previous good page); only a genuine 404
66	  // returns null below.
67	  const event = await getEventBySlugForMetadata(slug);
68	  if (!event) return { title: "No event found" };
69	  // Use canonical derived from the event itself to avoid locking old slugs
70	  // into metadata; this helps consolidate SEO to the canonical path.
71	  const canonical = `${siteUrl}${withLocalePath(`/e/${event.slug}`, locale)}`;
72	  return generateEventMetadata(event, canonical, undefined, locale);
73	}
74	
75	// Main page component — sync, unwraps params with use() and returns a Suspense
76	// boundary immediately so the static shell (layout) can flush before any async
77	// work. All async logic (locale, event fetch, translations, redirects) lives
78	// inside EventPageContent and streams in under the EventDetailSkeleton fallback.
79	export default function EventPage({
80	  params,
81	}: {
82	  params: Promise<{ eventId: string }>;
83	}) {
84	  const { eventId: slug } = use(params);
85	
86	  // Fallback combines the visual skeleton (aria-hidden) with a minimal
87	  // sr-only h1 derived from the slug — ensures crawlers see a heading even
88	  // if the Suspense stream fails (broken env, error boundary, etc.).
89	  return (
90	    <Suspense
91	      fallback={
92	        <>
93	          <h1 className="sr-only">{slug.replace(/-/g, " ")}</h1>
94	          <EventDetailSkeleton />
95	        </>
96	      }
97	    >
98	      <EventPageContent slug={slug} />
99	    </Suspense>
100	  );
101	}
102	
103	async function EventPageContent({
104	  slug,
105	}: {
106	  slug: string;
107	}): Promise<JSX.Element> {
108	  // Opt out of cacheComponents caching FIRST, before any data fetch whose
109	  // result drives JSX shape (relatedEvents JSON-LD, howTo JSON-LD, breadcrumbs,
110	  // LCP preload, sticky CTA, weather block, past-event banner — all conditional).
111	  // With cacheComponents, every await is a cache point: if connection() runs
112	  // after data fetches, the prerender path can cache a tree shape that doesn't
113	  // match the resume → "Expected Fragment but got script" PPR errors.
114	  await connection();
115	
116	  // Kick off event fetch and locale resolution in parallel — both are
117	  // independent operations and locale resolution shouldn't block the API call.
118	  const [locale, event] = await Promise.all([
119	    rootLocale() as Promise<AppLocale>,
120	    getEventBySlug(slug),
121	  ]);
122	
123	  // With relaxed CSP we no longer require a nonce here; compute mobile on client
124	  const initialIsMobile = false;
125	
126	  if (!event) notFound();
127	  if (event.title === "CANCELLED") notFound();
128	
129	  // If the requested slug doesn't match the canonical one, redirect
130	  // to consolidate SEO. This prevents duplicate content issues and ensures
131	  // all traffic goes to the canonical URL for better rankings.
132	  // Default to enabled unless explicitly disabled via environment variable.
133	  const disableCanonicalRedirect =
134	    process.env.NEXT_PUBLIC_CANONICAL_REDIRECT === "0" ||
135	    process.env.CANONICAL_REDIRECT === "0";
136	  if (!disableCanonicalRedirect && slug !== event.slug && event.slug) {
137	    redirect(withLocalePath(`/e/${event.slug}`, locale));
138	  }
139	
140	  const eventSlug = event?.slug ?? "";
141	  const title = event?.title ?? "";
142	  const rawCityName = event.city?.name || "";
143	  const rawRegionName = event.region?.name || "";
144	  const cityName = formatPlaceName(rawCityName);
145	  const regionName = formatPlaceName(rawRegionName);
146	  const citySlug = event.city?.slug;
147	  const regionSlug = event.region?.slug;
148	  const primaryPlaceSlug = citySlug || regionSlug || "catalunya";
149	  const sponsorFallbackPlaces =
150	    citySlug && regionSlug
151	      ? [regionSlug].filter((p) => p !== primaryPlaceSlug)
152	      : undefined;
153	  const primaryCategorySlug = event.categories?.[0]?.slug;
154	  const clientEvent = {
155	    id: event.id,
156	    slug: event.slug,
157	    title: event.title,
158	    endDate: event.endDate,
159	    categorySlug: primaryCategorySlug,
160	    placeSlug: citySlug ?? regionSlug,
161	    hasImage: Boolean(event.imageUrl),
162	    origin: event.origin,
163	    ownerId: event.owner?.id,
164	  };
165	  const explorePlaceHref = `/${primaryPlaceSlug}`;
166	  const exploreCategoryHref = primaryCategorySlug
167	    ? `/${primaryPlaceSlug}/${primaryCategorySlug}`
168	    : explorePlaceHref;
169	  const eventDateString = event.endDate
170	    ? `Del ${event.startDate} al ${event.endDate}`
171	    : `${event.startDate}`;
172	  const jsonData = generateJsonData({ ...event }, locale);
173	
174	  // Parallelize all translation fetches to eliminate waterfall (8 calls → 1 round trip)
175	  const [
176	    tStatus,
177	    tEvent,
178	    tCard,
179	    tCopy,
180	    tCategories,
181	    tEventsAround,
182	    tHowTo,
183	    tBreadcrumbs,
184	  ] = await Promise.all([
185	    getTranslations({ locale, namespace: "Utils.EventStatus" }),
186	    getTranslations({ locale, namespace: "Components.EventPage" }),
187	    getTranslations({ locale, namespace: "Components.CardContent" }),
188	    getTranslations({ locale, namespace: "Utils.EventCopy" }),
189	    getTranslations({ locale, namespace: "Config.Categories" }),
190	    getTranslations({ locale, namespace: "Components.EventsAround" }),
191	    getTranslations({ locale, namespace: "Components.HowTo" }),
192	    getTranslations({ locale, namespace: "Components.Breadcrumbs" }),
193	  ]);
194	  const primaryCategoryLabel = primaryCategorySlug
195	    ? getLocalizedCategoryLabelFromConfig(
196	      primaryCategorySlug,
197	      event.categories?.[0]?.name || primaryCategorySlug,
198	      tCategories
199	    )
200	    : "";
201	  const statusLabels = buildEventStatusLabels(tStatus);
202	  const eventCopyLabels: EventCopyLabels = {
203	    sentence: {
204	      verbSingular: tCopy("sentence.verbSingular"),
205	      verbPlural: tCopy("sentence.verbPlural"),
206	      dateRange: tCopy("sentence.dateRange", {
207	        start: "{start}",
208	        end: "{end}",
209	      }),
210	      dateSingle: tCopy("sentence.dateSingle", {
211	        nameDay: "{nameDay}",
212	        start: "{start}",
213	      }),
214	      sentence: tCopy("sentence.sentence", {
215	        title: "{title}",
216	        verb: "{verb}",
217	        date: "{date}",
218	        time: "{time}",
219	        place: "{place}",
220	      }),
221	      timeSuffix: tCopy("sentence.timeSuffix", { time: "{time}" }),
222	      timeSuffixRange: tCopy("sentence.timeSuffixRange", {
223	        start: "{start}",
224	        end: "{end}",
225	      }),
226	      placeSuffix: tCopy("sentence.placeSuffix", { place: "{place}" }),
227	    },
228	  };
229	  const temporalStatus: EventTemporalStatus = computeTemporalStatus(
230	    event.startDate,
231	    event.endDate,
232	    undefined,
233	    event.startTime,
234	    event.endTime,
235	    statusLabels
236	  );
237	
238	  const shouldShowFavoriteButton = Boolean(event.slug);
239	  const favoriteLabels = {
240	    add: tCard("favoriteAddAria"),
241	    remove: tCard("favoriteRemoveAria"),
242	  };
243	
244	  // Build intro text via shared utils (no assumptions)
245	  const introText = await buildEventIntroText(event, eventCopyLabels, locale);
246	
247	  // Prepare place data for LatestNewsSection (streamed separately)
248	  const placeLabel = cityName || regionName || "Catalunya";
249	  const placeType: "region" | "town" = event.city ? "town" : "region";
250	  const newsHref = withLocalePath(
251	    primaryPlaceSlug === "catalunya" ? "/noticies" : `/noticies/${primaryPlaceSlug}`,
252	    locale
253	  );
254	
255	  // Generate JSON-LD for related events (server-side for SEO)
256	  const relatedEventsJsonData =
257	    event.relatedEvents && event.relatedEvents.length > 0
258	      ? {
259	        // Anchor the ItemList @id to the event's canonical URL with a stable
260	        // fixed fragment — avoids homepage-scoped @id and fragile title slugs.
261	        "@id": `${siteUrl}${withLocalePath(`/e/${event.slug}`, locale)}#related-events`,
262	        "@context": "https://schema.org",
263	        "@type": "ItemList",
264	        name: "Related Events",
265	        url: `${siteUrl}${withLocalePath(`/e/${event.slug}`, locale)}`,
266	        numberOfItems: event.relatedEvents.length,
267	        itemListElement: event.relatedEvents
268	          .slice(0, 10) // Limit for performance
269	          .map((relatedEvent, index) => {
270	            try {
271	              return {
272	                "@type": "ListItem",
273	                position: index + 1,
274	                item: generateJsonData(relatedEvent, locale),
275	              };
276	            } catch (err) {
277	              console.error(
278	                "Error generating JSON-LD for related event:",
279	                relatedEvent.id,
280	                err
281	              );
282	              return null;
283	            }
284	          })
285	          .filter(Boolean),
286	      }
287	      : null;
288	
289	  const howToSteps = [
290	    tHowTo("step1"),
291	    tHowTo("step2"),
292	    tHowTo("step3"),
293	  ];
294	  const howToJsonData = generateHowToSchema(
295	    tHowTo("name", { title: title || "Esdeveniment" }),
296	    howToSteps
297	  );
298	
299	  // Generate BreadcrumbList JSON-LD
300	  // Ensure breadcrumb name is never empty (required by Google structured data)
301	  const breadcrumbName = (() => {
302	    if (title) return title;
303	    if (placeLabel) return `Esdeveniment a ${placeLabel}`;
304	    return "Esdeveniment";
305	  })();
306	
307	  // Build breadcrumb items with region for cities (SEO: geographic hierarchy)
308	  // Structure: Inici > Region > City > Event  OR  Inici > Region > Event (if no city)
309	  const hasCity = Boolean(citySlug);
310	  const hasRegion = Boolean(regionSlug);
311	
312	  // Build breadcrumb items array with localized URLs
313	  const homeLabel = tBreadcrumbs("home");
314	  const breadcrumbItems = [
315	    { name: homeLabel, url: toLocalizedUrl("/", locale) },
316	    // Add region (comarca) if available
317	    ...(hasRegion ? [{ name: regionName, url: toLocalizedUrl(`/${regionSlug}`, locale) }] : []),
318	    // Add city if different from region
319	    ...(hasCity ? [{ name: cityName, url: toLocalizedUrl(`/${citySlug}`, locale) }] : []),
320	    // Add event
321	    { name: breadcrumbName, url: toLocalizedUrl(`/e/${event.slug}`, locale) },
322	  ];
323	  const breadcrumbJsonLd = generateBreadcrumbList(breadcrumbItems);
324	
325	  // Preload LCP hero image — React 19 hoists <link> to <head> automatically.
326	  // Uses responsive srcSet so the browser picks the right width for the viewport,
327	  // instead of always downloading the full 1200px version on mobile.
328	  const lcpSources = event.imageUrl
329	    ? buildResponsivePictureSourceUrls(event.imageUrl, undefined, {
330	      quality: getOptimalImageQuality({ isPriority: true, isExternal: true }),
331	    }, getResponsiveWidths("hero"))
332	    : null;
333	  const lcpSizes = getOptimalImageSizes("hero");
334	
335	  return (
336	    <>
337	      {/* Preload LCP hero image for faster Largest Contentful Paint */}
338	      {lcpSources && (
339	        <link
340	          rel="preload"
341	          as="image"
342	          imageSrcSet={lcpSources.webpSrcSet}
343	          imageSizes={lcpSizes}
344	          type="image/webp"
345	          fetchPriority="high"
346	        />
347	      )}
348	      {/* Main Event JSON-LD */}
349	      <JsonLdServer
350	        id={event.id ? String(event.id) : undefined}
351	        data={jsonData}
352	      />
353	      {/* Related Events JSON-LD */}
354	      {relatedEventsJsonData && (
355	        <JsonLdServer
356	          id={`related-events-${event.id}`}
357	          data={relatedEventsJsonData}
358	        />
359	      )}
360	      {/* HowTo JSON-LD for SEO strategy 5 */}
361	      {howToJsonData && (
362	        <JsonLdServer id={`howto-${event.id}`} data={howToJsonData} />
363	      )}
364	      {/* Breadcrumbs JSON-LD */}
365	      {breadcrumbJsonLd && (
366	        <JsonLdServer id={`breadcrumbs-${event.id}`} data={breadcrumbJsonLd} />
367	      )}
368	      <div className="w-full bg-background pb-10">
369	        <div className="container flex flex-col gap-section-y min-w-0">
370	          <article className="w-full flex flex-col gap-section-y">
371	            {/* PWA back button — only renders in installed standalone mode */}
372	            <PwaBackButton fallbackHref="/" />
373	            {/* Visible Breadcrumbs for internal linking — full width */}
374	            <Breadcrumbs
